// The dedicated worker the SDK starts for the core (RFC 0009, "Open and
// close"; Carsten, 2026-11-12, NOC-274). It loads the core's WebAssembly
// module, shipped next to it in the package's build output, and answers
// each message, one bridge request in CBOR, with the bridge's answer, in
// order, as `{answer}`. The core's fold events, which the SDK's
// subscriptions re-run on, go to the page as `{event}`. The module's glue is
// generated by wasm-bindgen at build time (packages/sdk/build.mjs); it is
// not in src/.

import { decode, encode } from "./cbor.ts";
// @ts-expect-error: generated into dist/wasm/ by the build step.
import init, { Core } from "./wasm/nocentraldb_wasm.js";

type Bridge = {
  handle(request: Uint8Array): Promise<Uint8Array>;
  listen(listener: (event: Uint8Array) => void): void;
};

const post = (message: { answer?: Uint8Array; event?: Uint8Array }) => {
  const bytes = message.answer ?? message.event;
  (self as unknown as Worker).postMessage(message, bytes ? [bytes.buffer] : []);
};

const ready: Promise<Bridge> = init({
  module_or_path: new URL("./wasm/nocentraldb_wasm_bg.wasm", import.meta.url),
}).then(() => {
  const core = new Core() as Bridge;
  core.listen((event) => post({ event }));
  return core;
});

// Requests are answered one at a time, in the order they came.
let queue: Promise<unknown> = Promise.resolve();

const answer = async (request: Uint8Array): Promise<Uint8Array> => {
  try {
    return await (await ready).handle(request);
  } catch (error) {
    // The module did not load, or the core failed: the request still gets
    // an answer, so the page never waits for one that does not come.
    const { id } = decode(request) as { id: number };
    return encode({
      id,
      error: {
        code: "storageFailed",
        message: `the core failed: ${String(error)}`,
      },
    });
  }
};

self.onmessage = (event: MessageEvent<Uint8Array>) => {
  const request = event.data;
  queue = queue.then(async () => {
    post({ answer: await answer(request) });
  });
};
